impl<T: gx::Real> Direction<(), T, gx::Extrinsic> {
    /// The exponential, `exp(z + V) = exp(z) (C(VÂ²) + S(VÂ²) V)` with `V` the rest and
    /// `VÂ²` a Study number (`cosh |v| + sinh |v| vÌ` for a vector of positive square, `cos` and
    /// `sin` for a negative one). A `Motor`, not a `gx::Unit`: `x ~x` need not be 1.
    #[inline]
    #[allow(unused_variables)]
    pub fn exp(self) -> Motor<(), T> {
        T::vectorize(#[inline(always)] move || {
        let x = self.c;
        let [c0, c1, s0, s1] = gx::__private::study::exp_coeffs_central(-1, T::from_i64(0), T::from_i64(0), T::from_i64(0), T::from_i64(0));
        let t0 = x[0] * s0;
        let t1 = x[1] * s0;
        let t2 = x[2] * s0;
        let t3 = x[3] * s0;
        Motor::from_coeffs([c0, T::from_i64(0), T::from_i64(0), T::from_i64(0), T::from_i64(0), T::from_i64(0), T::from_i64(0), T::from_i64(0), T::from_i64(0), T::from_i64(0), T::from_i64(0), t0, t1, t2, t3, T::from_i64(0)])
        })
    }

}

#[doc = "A hyperplane through the origin event, `a x + b y + c z + d t = 0`: the non-degenerate part of a hyperplane, which reads a step: a clock's or a ruler's readout. It pairs with `Direction`s, its complement."]
///
/// Blades, in coefficient order: `[e1, e2, e3, e4]`.
///
/// `S` lists the open slots: `OriginHyperplane` (that is, `OriginHyperplane<()>`) is a value, `OriginHyperplane<(A,)>` a
/// linear map from `A`, `OriginHyperplane<(A, B)>` a bilinear map. `T` is the coefficient type. `O` is
/// the orientation of the output, extrinsic by default (ADR-051).
#[repr(C)]
pub struct OriginHyperplane<S: gx::Slots = (), T: gx::Coef = f64, O: gx::Orientation = gx::Extrinsic> {
    /// Coefficients, output first: `c[i]` is the slot array of blade `i`.
    pub c: [S::Arr<T>; 4],
    o: core::marker::PhantomData<O>,
}

impl<S: gx::Slots, T: gx::Coef, O: gx::Orientation> Clone for OriginHyperplane<S, T, O> {
    #[inline(always)]
    fn clone(&self) -> Self {
        *self
    }
}

impl<S: gx::Slots, T: gx::Coef, O: gx::Orientation> Copy for OriginHyperplane<S, T, O> {}

impl<S: gx::Slots, T: gx::Coef, O: gx::Orientation> PartialEq for OriginHyperplane<S, T, O> {
    fn eq(&self, other: &Self) -> bool {
        self.c == other.c
    }
}

impl<S: gx::Slots, T: gx::Coef, O: gx::Orientation> core::fmt::Debug for OriginHyperplane<S, T, O> {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        let mut d = f.debug_struct(if O::SIGN < 0 { "intrinsic OriginHyperplane" } else { "OriginHyperplane" });
        for (b, c) in <OriginHyperplane as gx::Kind>::BLADES.iter().zip(self.c.iter()) {
            d.field(b, c);
        }
        d.finish()
    }
}

