impl<T: gx::Coef, O: gx::Orientation> gx::__private::NewtonStep for OriginHyperplane<(), T, O> {
    /// `(3 â x ~x) x / 2`: one Newton step towards `x ~x = 1`, without a square root.
    #[inline(always)]
    fn newton_step(self) -> Self {
        let x = self.c;
        let t1 = x[1] * x[1];
        let t2 = x[2] * x[2];
        let t4 = x[0].mul_add(x[0], t1);
        let t5 = (-x[3]).mul_add(x[3], t2);
        let t6 = t4 + t5;
        let t8 = (-t6).mul_add(T::from_ratio(1, 3), T::from_i64(1));
        let t9 = x[0] * t8;
        let t10 = x[1] * t8;
        let t11 = x[2] * t8;
        let t12 = x[3] * t8;
        let t13 = t9 * T::from_ratio(3, 2);
        let t14 = t10 * T::from_ratio(3, 2);
        let t15 = t11 * T::from_ratio(3, 2);
        let t16 = t12 * T::from_ratio(3, 2);
        OriginHyperplane::from_coeffs([t13, t14, t15, t16])
    }

    #[inline(always)]
    fn note_renormalize() {
        T::note_renormalize();
    }
}

